<script setup>
import { ref, shallowRef, reactive, computed, watch, onBeforeUnmount, nextTick } from 'vue'
const canvas = ref(null), source = shallowRef(null), original = ref(''), error = ref(''), name = ref('image'), compare = ref(false)
const defaults = { brightness:100, contrast:100, saturation:100, temperature:0, grayscale:0, sepia:0, blur:0 }
const settings = reactive({...defaults})
const sliders = [ ['brightness','亮度',0,200,1,'%'], ['contrast','對比度',0,200,1,'%'], ['saturation','飽和度',0,200,1,'%'], ['temperature','色溫（冷暖）',-100,100,1,''], ['grayscale','灰階',0,100,1,'%'], ['sepia','復古色調',0,100,1,'%'], ['blur','模糊',0,12,.5,'px'] ]
const format = ref('image/png'), quality = ref(.9)
const filter = computed(()=>`brightness(${settings.brightness}%) contrast(${settings.contrast}%) saturate(${settings.saturation}%) grayscale(${settings.grayscale}%) sepia(${settings.sepia}%) blur(${settings.blur}px)`)
let generation = 0, frame = 0
function reset(){Object.assign(settings,defaults);compare.value=false}
function preset(id){reset();if(id==='warm')Object.assign(settings,{temperature:40,saturation:115});if(id==='cool')Object.assign(settings,{temperature:-40,saturation:95});if(id==='retro')Object.assign(settings,{sepia:65,contrast:90,saturation:80});if(id==='mono')settings.grayscale=100}
async function load(e){const file=e.target.files?.[0];e.target.value='';if(!file)return;const token=++generation;error.value='';const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();if(token!==generation){URL.revokeObjectURL(url);return}if(img.naturalWidth*img.naturalHeight>24000000)throw new Error('圖片超過 2400 萬像素，請先縮小圖片。');if(original.value)URL.revokeObjectURL(original.value);original.value=url;source.value=img;name.value=file.name.replace(/\.[^.]+$/,'');reset();await nextTick();render()}catch(err){URL.revokeObjectURL(url);if(token===generation)error.value=err.message||'無法讀取圖片'}}
function render(){const c=canvas.value,img=source.value;if(!c||!img)return;if(c.width!==img.naturalWidth)c.width=img.naturalWidth;if(c.height!==img.naturalHeight)c.height=img.naturalHeight;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.clearRect(0,0,c.width,c.height);ctx.filter=compare.value?'none':filter.value;ctx.drawImage(img,0,0);ctx.filter='none';if(!compare.value&&settings.temperature!==0){const pixels=ctx.getImageData(0,0,c.width,c.height),d=pixels.data,t=settings.temperature*.55;for(let i=0;i<d.length;i+=4){d[i]+=t;d[i+2]-=t}ctx.putImageData(pixels,0,0)}}
watch([settings,compare],()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(render)},{deep:true,flush:'post'})
async function save(){if(!source.value)return;compare.value=false;await nextTick();render();const c=canvas.value;const out=document.createElement('canvas');out.width=c.width;out.height=c.height;const ctx=out.getContext('2d');if(format.value==='image/jpeg'){ctx.fillStyle='#fff';ctx.fillRect(0,0,out.width,out.height)}ctx.drawImage(c,0,0);out.toBlob(blob=>{if(!blob){error.value='無法輸出圖片';return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${name.value}-adjusted.${blob.type==='image/jpeg'?'jpg':blob.type==='image/webp'?'webp':'png'}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)},format.value,quality.value)}
onBeforeUnmount(()=>{generation++;cancelAnimationFrame(frame);if(original.value)URL.revokeObjectURL(original.value)})
</script>
<template>
<section class="adjust-tool">
 <div class="adjust-top"><label class="adjust-upload">選擇本機圖片<input type="file" accept="image/*" @change="load"></label><button @click="reset" :disabled="!source">重設全部</button><button @click="compare=!compare" :disabled="!source">{{compare?'查看調整後':'查看原圖'}}</button></div>
 <p v-if="error" role="alert" class="adjust-error">{{error}}</p>
 <div class="adjust-grid"><div class="adjust-preview"><canvas v-show="source" ref="canvas" aria-label="圖片預覽"></canvas><p v-if="!source">請先選擇圖片，即可開始調整。</p><span v-if="source" class="adjust-tag">{{compare?'原始圖片':'調整後'}} · {{source.naturalWidth}} × {{source.naturalHeight}}</span></div>
 <div class="adjust-controls"><h3>色彩調整</h3><div class="adjust-presets"><button v-for="p in [['warm','暖色'],['cool','冷色'],['retro','復古'],['mono','黑白']]" :key="p[0]" @click="preset(p[0])">{{p[1]}}</button></div><label v-for="s in sliders" :key="s[0]" class="adjust-slider"><span>{{s[1]}} <strong>{{settings[s[0]]}}{{s[5]}}</strong></span><input type="range" :min="s[2]" :max="s[3]" :step="s[4]" v-model.number="settings[s[0]]"></label><label>輸出格式 <select v-model="format"><option value="image/png">PNG</option><option value="image/jpeg">JPEG</option><option value="image/webp">WebP</option></select></label><label v-if="format!=='image/png'" class="adjust-slider"><span>品質 {{Math.round(quality*100)}}%</span><input type="range" min=".1" max="1" step=".05" v-model.number="quality"></label><button class="adjust-save" :disabled="!source" @click="save">下載調整後圖片</button></div></div>
 <p class="adjust-note">圖片僅在本機瀏覽器處理。色溫為簡易冷暖色偏調整，原始檔案不會被修改。</p>
</section>
</template>
<style scoped>
.adjust-tool{margin-top:16px;color:#203547}.adjust-top,.adjust-presets{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}.adjust-upload{background:#be185d;color:white;border-radius:12px;padding:10px 14px;font-weight:700;cursor:pointer}.adjust-upload input{display:block;max-width:230px;margin-top:6px;font-size:12px}.adjust-grid{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(250px,1fr);gap:16px}.adjust-preview{position:relative;min-height:320px;display:grid;place-items:center;background:repeating-conic-gradient(#e2e8f0 0% 25%,#f8fafc 0% 50%) 50% / 24px 24px;border-radius:20px;overflow:hidden;padding:16px}.adjust-preview canvas{display:block;max-width:100%;max-height:65vh;width:auto;height:auto;object-fit:contain}.adjust-tag{position:absolute;bottom:10px;left:10px;background:#ffffffef;padding:6px 10px;border-radius:8px;font-size:12px}.adjust-controls{background:#fff;border-radius:20px;padding:18px;display:grid;gap:12px}.adjust-controls h3{font-size:20px;margin:0;font-weight:800}.adjust-slider{display:grid;gap:5px}.adjust-slider span{display:flex;justify-content:space-between}.adjust-slider input{width:100%;accent-color:#be185d}.adjust-controls select{padding:6px;border:1px solid #cbd5e1;border-radius:8px}.adjust-controls .adjust-save{background:#be185d;color:#fff}.adjust-tool button:disabled{opacity:.45;cursor:not-allowed}.adjust-error{color:#b91c1c}.adjust-note{font-size:13px;color:#64748b;margin-top:12px}@media(max-width:760px){.adjust-grid{grid-template-columns:1fr}.adjust-preview{min-height:220px}}
</style>
